-- Programme réel Habitudes & Défis — 30 premiers jours (FR, version 1)
-- Décision Dr Justin Tshims du 26/10/2026, 21h36 (« JE VALIDE ») sur le document de relecture :
-- 30 lectures approuvées, 16 rendez-vous et consignes, nom du programme, ouverture sans texte de l'Amidah.
-- Lien HD et offre gratuite créés INACTIFS : aucune ouverture publique tant qu'ils ne sont pas activés.
insert into seneve.programmes(programme_id,nom,langue,description,duree_jours,type_parcours,quota_coach_jour,messages_par_jour,delai_apres_achat_jours)
values('HABITUDES_DEFIS_30J_FR_V1','Habitudes & Défis — les 30 premiers jours','fr',
 'Six mois de pratique quotidienne : 30 premiers jours gratuits, puis mois 2 à 6 inclus dans l''abonnement Continuité.',
 30,'habitudes_defis',50,1,0);
insert into seneve.programme_versions(programme_id,version,etat,valide_par,date_validation,publiee_le)
values('HABITUDES_DEFIS_30J_FR_V1',1,'publiee','Dr Justin Tshims — accord du 26/10/2026 (lectures) et validation du 26/10/2026 21h36',now(),now());
with j(jour,titre,objectif,texte,question,source) as (values
 (1,'Commencer avec ce qui est possible','Choisir un premier pas réaliste.','Commence avec la journée qui est devant toi. Le chapitre sur la fidélité invite à prendre soin des responsabilités ordinaires. Choisis un rendez-vous que tu peux réellement honorer aujourd’hui, puis garde les autres repères à leur juste place. Le suivi t’aide à nommer tes actions ; il ne mesure ni ta foi ni ta valeur.','Quel rendez-vous veux-tu préparer en premier ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 117–118 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (2,'Faire une place à l’essentiel','Relire ses priorités concrètes.','Une priorité devient visible dans la manière d’utiliser son temps. Avant de remplir ta journée, regarde la place que tu souhaites donner à la prière, à la lecture et à tes responsabilités. Tu peux ajuster les heures proposées à tes contraintes. Chercher un ordre plus juste commence par une décision concrète, à ta portée.','Quel ajustement rendrait ta journée plus cohérente avec tes priorités ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 1, pages imprimées 9–10 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (3,'Préparer son rendez-vous de prière','Faciliter un temps de prière personnel.','Le livre présente la prière comme une relation qui accompagne les décisions ordinaires. Prépare un endroit ou un moment où tu pourras te recueillir sans précipitation. La prière proposée peut soutenir ce temps ; tu peux aussi prier avec tes propres mots. Déclare ensuite ce que tu as réellement vécu, sans te comparer aux autres.','Qu’est-ce qui t’aide à entrer calmement dans la prière ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, pages imprimées 144–145 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (4,'Lire pour comprendre','Associer lecture et réflexion.','Accorde une attention réelle à ce que tu lis. Le chapitre sur le discernement relie l’écoute à la vie quotidienne. Pendant ta lecture biblique, prends le temps de repérer une idée que tu souhaites comprendre davantage. Tu n’as pas besoin de produire une longue réponse. Une question honnête peut devenir le point de départ de ta réflexion.','Quelle idée ou question gardes-tu de ta lecture ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, pages imprimées 144–145 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (5,'Honorer une petite responsabilité','Reconnaître la valeur d’une tâche ordinaire.','Le livre illustre la fidélité par des gestes ordinaires : une responsabilité assumée, une parole tenue, un travail poursuivi. Choisis une tâche déjà présente dans ta journée et accorde-lui l’attention qu’elle mérite. Il ne s’agit pas d’ajouter des obligations pour remplir une liste. Observe plutôt comment tu prends soin de ce qui t’est déjà confié.','Quelle responsabilité ordinaire mérite ton attention aujourd’hui ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 117–118 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (6,'Prendre soin de son rythme','Adapter les repères à ses capacités.','La fidélité se pratique à partir de ce qui t’est confié et de tes possibilités réelles. Le module propose aussi du mouvement doux et un rythme de repos. Adapte ces repères à ta situation, comme le prévoit le cahier des charges. Décrire une réalisation partielle ou demander de l’aide est plus utile que déclarer un effort que tu n’as pas fait.','Quel horaire ou effort doit être adapté à ta situation ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 117–118 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (7,'Relire une première semaine','Observer sans se condamner.','Prends un moment pour relire tes premiers jours. Repère un geste que tu as pu répéter et une difficulté qui revient. Le chapitre sur les petites choses invite à regarder la pratique quotidienne plutôt que les apparences. Ton bilan sert à préparer la suite. Un rendez-vous manqué ne supprime ni les actions déjà faites ni la possibilité de reprendre.','Que souhaites-tu conserver et qu’aimerais-tu ajuster ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 117–118 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (8,'Relier prière et action','Préparer une responsabilité concrète.','Le chapitre sur le travail rapproche la prière de l’action. Présente ta journée dans la prière, puis identifie une responsabilité concrète à assumer. Selon ta situation, elle peut concerner ton emploi, tes études, une recherche ou une tâche familiale. Une difficulté d’accès au travail ne dit rien de ta valeur. Avance à partir de ce qui est effectivement possible.','Quel pas concret accompagne ta prière aujourd’hui ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, pages imprimées 58–59 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (9,'Apprendre pour mieux servir','Donner un sens à la lecture professionnelle.','La lecture professionnelle est un rendez-vous pour apprendre quelque chose d’utile à ton activité. Choisis un support en rapport avec ton métier, tes études ou un projet réel. Pendant ce temps, cherche une idée que tu pourrais comprendre ou appliquer. La durée proposée t’aide à t’organiser ; ta déclaration doit refléter la lecture réellement effectuée.','Quelle idée utile as-tu retenue ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, pages imprimées 58–59 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (10,'Tenir une parole donnée','Relire un engagement avec honnêteté.','Parmi les exemples de fidélité, le livre place la parole donnée. Pense à un engagement concret que tu as déjà pris. Tu peux le respecter, préciser ce qui reste possible ou prévenir honnêtement si tu ne peux pas le tenir. Cette réflexion porte sur un acte précis. Elle ne demande pas de te définir à partir d’un échec.','Quel engagement mérite une réponse honnête de ta part ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 117–118 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (11,'Prendre soin de ce qui est confié','Respecter un bien ou une responsabilité partagée.','L’exemple de Joseph met en lumière le soin apporté à ce qui appartient à autrui. Regarde une responsabilité ou un bien que l’on t’a confié : du matériel, un document, un espace ou du temps. Réfléchis à la manière de le respecter aujourd’hui. Une attention discrète peut avoir autant de sens qu’une action très visible.','De quoi es-tu responsable, même si cela ne t’appartient pas ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 119–120 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (12,'Faire une chose avec attention','Privilégier une action réellement menée.','Le travail dont parle le livre appelle un engagement concret. Choisis une étape raisonnable dans une tâche déjà prévue et donne-lui ton attention. Tu peux ensuite reconnaître ce qui est terminé et ce qui reste en cours. Le suivi n’exige pas de transformer une action partielle en réussite complète. Il t’aide à reprendre au bon endroit.','Quelle étape as-tu réellement pu mener aujourd’hui ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 3, pages imprimées 58–59 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (13,'Apprendre sans se comparer','Se concentrer sur ses propres possibilités.','La lecture de la parabole des talents proposée dans le livre souligne des capacités différentes. Ton rythme n’a pas à reproduire celui d’une autre personne. Pour tes lectures et tes autres rendez-vous, observe les moyens dont tu disposes et ce que tu peux développer. La comparaison ne remplace pas un regard précis sur ta propre pratique.','Quel progrès peux-tu reconnaître sans te comparer ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 118 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (14,'Faire le point sur son organisation','Choisir un ajustement pour la suite.','Relis les rendez-vous de cette deuxième semaine. Certaines difficultés viennent d’un horaire peu réaliste ou d’une préparation insuffisante. Choisis un ajustement simple : préparer un livre, déplacer un créneau ou mieux anticiper une contrainte. Tu peux conserver tes réalisations et modifier ton organisation. Le bilan ne te demande pas de recommencer toute ton histoire.','Quel ajustement simple veux-tu essayer ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 117–118 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (15,'Reconnaître ce qui est déjà là','Nourrir la gratitude du quotidien.','Le chapitre sur l’argent distingue la possession de l’attachement. Pour ta gratitude du matin ou du soir, prends le temps de reconnaître aussi ce qui ne se mesure pas en biens : une relation, un apprentissage, une aide reçue. Reconnaître ces choses n’oblige pas à nier tes difficultés. Cela élargit simplement le regard porté sur ta journée.','De quoi peux-tu être reconnaissant tout en restant honnête sur tes difficultés ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 4, pages imprimées 79–80 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (16,'Observer une habitude de dépense','Mieux comprendre une pratique personnelle.','Le livre propose d’observer ses dépenses pour mieux comprendre ses habitudes. Si tu souhaites explorer ce sujet, relève pour toi un exemple concret et ce qu’il t’apprend. Tu n’as pas à inscrire de montant ni de détail financier dans ce module. Cette réflexion ne remplace pas un conseil adapté à ta situation et ne promet aucun résultat financier.','Qu’as-tu appris en observant cette habitude ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 128 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (17,'Réfléchir à sa générosité','Distinguer réflexion et pression de donner.','Le chapitre sur la dîme et l’offrande ouvre une réflexion sur la place du don. Prends le temps d’examiner ta motivation et tes possibilités sans précipitation. Cette fiche ne te demande aucun paiement et ne conditionne pas ta progression à un don. Tu peux garder cette réflexion personnelle et approfondir les questions qui restent ouvertes.','Qu’est-ce qui motive ta générosité aujourd’hui ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 2, pages imprimées 38–39 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (18,'Choisir avec plus de liberté','Examiner un attachement concret.','L’argent peut servir des besoins et des projets ; le livre invite aussi à examiner la place qu’il prend dans le cœur. Observe une envie ou une pression de comparaison qui influence tes choix. Tu peux la nommer sans te juger ni prendre une décision immédiate. Comprendre une habitude est une première étape pour choisir avec davantage de recul.','Quelle pression aimerais-tu regarder avec plus de recul ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 4, pages imprimées 79–80 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (19,'Voir un besoin proche','Porter attention à une personne.','Le chapitre sur l’aide aux personnes vulnérables ramène l’attention vers des besoins concrets. Dans ton entourage, sois attentif à une personne qui pourrait avoir besoin d’écoute, de présence ou d’une aide adaptée. N’expose pas sa situation dans le suivi. La compassion commence par un regard respectueux ; elle n’exige pas de te mettre en scène.','Quel besoin peux-tu reconnaître avec respect et discrétion ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 5, pages imprimées 100–101 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (20,'Servir avec discrétion','Envisager une aide adaptée et libre.','Après avoir reconnu un besoin, réfléchis à une aide réellement adaptée à tes possibilités et à ce que la personne souhaite. Il peut s’agir de temps, d’écoute ou d’un service. Aucune somme ni preuve publique n’est demandée. Cette piste de réflexion ne devient pas automatiquement une activité obligatoire du parcours.','Quelle aide serait utile, souhaitée et à ta portée ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 5, pages imprimées 100–101 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (21,'Relire gratitude et attention aux autres','Reconnaître ce qui a changé dans son regard.','Relis les derniers jours : ta manière de reconnaître ce que tu reçois, de regarder tes habitudes et d’être attentif aux autres. Note mentalement ce qui t’a aidé et ce qui demeure difficile. Le bilan ne transforme pas la générosité en classement. Il t’aide à discerner une attitude que tu aimerais continuer à cultiver.','Quelle attitude souhaites-tu garder pour la prochaine semaine ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 4, pages imprimées 79–80 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (22,'Ralentir avant de décider','Faire une place au discernement.','Le dernier chapitre décrit la pression des décisions prises dans l’urgence. Pour une décision ordinaire qui te préoccupe, prends un temps de recul et de prière. Distingue les faits connus des pressions que tu ressens. Cette fiche ne prétend pas te transmettre une réponse de Dieu ni décider à ta place.','Qu’as-tu besoin de comprendre avant de décider ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, pages imprimées 134–135 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (23,'Écouter avec attention','Relier l’écoute d’une prédication à la réflexion.','Pendant ton temps d’écoute, cherche à comprendre le message et sa relation avec ta vie quotidienne. Une prédication choisie personnellement ou recommandée après validation peut soutenir ta réflexion. Tu peux retenir une idée et une question. Le fait d’ouvrir un lien ou de lancer un audio ne dit pas, à lui seul, que tu as écouté.','Quelle idée mérite d’être approfondie après ton écoute ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, pages imprimées 144–145 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (24,'Ne pas confondre vitesse et fidélité','Choisir un rythme soutenable.','Une décision rapide n’est pas toujours une décision mieux comprise. Regarde ton agenda et les rendez-vous que tu souhaites conserver. Tu peux distinguer une contrainte réelle d’une urgence ajoutée. Préserver un rythme soutenable aide à rester attentif à ce que tu fais, sans transformer chaque retard en jugement sur toi-même.','Quelle urgence mérite d’être réévaluée ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 7, pages imprimées 134–135 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (25,'Préparer sa participation au culte','Adapter les créneaux à son assemblée.','Le module prévoit trois participations hebdomadaires au culte, avec des jours et heures personnalisables. Vérifie que tes créneaux correspondent à la vie réelle de ton assemblée et à tes contraintes. Une participation est déclarée par toi ; elle n’est pas déduite de ta présence dans l’application. Les situations d’impossibilité doivent pouvoir être signalées honnêtement.','Ton planning de culte correspond-il à tes possibilités réelles ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 117–118 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (26,'Reprendre après un rendez-vous manqué','Continuer sans effacer le chemin parcouru.','Un rendez-vous manqué mérite une réponse concrète plutôt qu’un effacement de tes efforts. Regarde ce qui l’a rendu difficile et prépare le prochain moment accessible. Tu peux déclarer une réalisation partielle ou demander de l’aide. Dans ce suivi, reprendre ne signifie pas supprimer tes lectures, tes prières ou les autres actions déjà confirmées.','Quel prochain rendez-vous peux-tu préparer simplement ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 117–118 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (27,'Reconnaître un besoin d’aide','Nommer une difficulté sans se réduire à elle.','La pratique régulière peut révéler des obstacles que l’on n’avait pas anticipés. Identifie une difficulté précise : horaire, compréhension, fatigue ou organisation. Tu peux demander de l’aide sans prétendre avoir terminé l’activité. La demande d’aide reste distincte de la réalisation et ne remet pas à zéro tes autres actions.','Sur quel point une aide te serait-elle utile ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 117–118 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (28,'Relire quatre semaines','Distinguer les acquis et les ajustements.','Prends une vue d’ensemble de ces quatre semaines. Repère les rendez-vous devenus plus faciles à préparer et ceux qui nécessitent encore une adaptation. Appuie-toi sur tes déclarations réelles, sans comparer tes chiffres à ceux d’une autre personne. Le bilan décrit une pratique ; il ne délivre pas un jugement sur ta vie spirituelle.','Qu’aimerais-tu continuer et qu’as-tu besoin d’adapter ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 117–118 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (29,'Préparer la continuité','Choisir ce que l’on souhaite poursuivre.','Reviens à tes priorités et aux habitudes qui les rendent concrètes. Choisis ce que tu souhaites poursuivre après cette première période et les moyens nécessaires pour y parvenir. Cette réflexion n’ouvre aucun accès payant et ne vaut pas accord de renouvellement. Les conditions d’une éventuelle suite doivent être présentées séparément et rester explicites.','Quelle habitude veux-tu soutenir dans la durée ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 1, pages imprimées 9–10 ; cahier Habitudes & Défis, sections 3–5 et 10–13.'),
 (30,'Faire un bilan honnête et paisible','Reconnaître le chemin parcouru et un prochain pas.','Relis le chemin parcouru pendant ces trente jours. Reconnais une action répétée, un apprentissage et une difficulté encore présente. Tu peux remercier pour ce qui a grandi et choisir un prochain pas réaliste. La fin de cette période n’efface pas ton histoire et ne déclenche aucun paiement automatique. Ton bilan reste un point d’appui pour la suite.','Quel prochain pas choisis-tu avec confiance et réalisme ?','Arrête de mendier des miracles, PDF français révisé fourni, chapitre 6, pages imprimées 117–118 ; cahier Habitudes & Défis, sections 3–5 et 10–13.')
)
