-- Sauvegarde des deux fonctions modifiées ci-dessous.
insert into seneve_private.sauvegardes_definitions(objet,definition,motif)
select p.oid::regprocedure::text,pg_get_functiondef(p.oid),'avant habitudes_programme_reel_30j'
 from pg_proc p where p.oid in ('seneve_private.hd_coach_excluded(uuid)'::regprocedure,'seneve.hd_progress_access_guard()'::regprocedure);
-- La garde des cultes s'applique aussi au programme réel.
do $$declare d text; a constant text := 'if e.programme_id=''HD_RECETTE_INSCRIPTION_FR_20261026'' then';
 n constant text := 'if e.programme_id in (''HD_RECETTE_INSCRIPTION_FR_20261026'',''HABITUDES_DEFIS_30J_FR_V1'') then';
begin d:=pg_get_functiondef('seneve.hd_progress_access_guard()'::regprocedure);
 if (length(d)-length(replace(d,a,'')))/length(a)<>1 then raise exception 'motif introuvable'; end if;
 execute replace(d,a,n); end$$;
-- Coach inclus pendant les mois 2 à 6 avec abonnement Continuité actif (décision du 26/10/2026, ligne « Coach »).
create or replace function seneve_private.hd_coach_excluded(p_enrollment_id uuid)
returns boolean language sql stable security definer set search_path='' as $f$
 select exists(select 1 from seneve.enrollments e
  where e.enrollment_id=p_enrollment_id
   and exists(select 1 from seneve.hd_programme_links known where known.programme_id=e.programme_id)
   and not exists(
    select 1 from seneve.hd_programme_links l
    join seneve.programme_versions v on v.programme_id=l.programme_id and v.version=l.version and v.etat in('publiee','archivee')
    join seneve.programmes pr on pr.programme_id=l.programme_id and pr.quota_coach_jour>0
    join seneve.hd_access_periods ap on ap.enrollment_id=e.enrollment_id and ap.participant_id=e.participant_id
     and (ap.mois between 2 and 6 or ap.cycle>1) and now()>=ap.debut and now()<ap.fin_exclue
    where l.programme_id=e.programme_id and l.version=e.version and l.langue=e.langue and l.actif and e.etat='active'
     and seneve.hd_droit_a(e.enrollment_id, now())
   ))
$f$;
